package br.com.orientec.backend.adapter.out.persistence.entity.os; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; @Entity @Table(name="ordem_servico_pendencia") public class OrdemServicoPendencia { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id") private Long id; @Column(name="ordem_servico_id") private Long ordemServicoId; @Column(name="tipo_pendencia_id") private Short tipoPendenciaId; @Column(name="descricao") private String descricao; @Column(name="data_inclusao") private java.time.OffsetDateTime dataInclusao; @Column(name="data_resolucao") private java.time.OffsetDateTime dataResolucao; @Column(name="resolvida") private boolean resolvida; @Column(name="usuario_codigo") private Long usuarioCodigo; public OrdemServicoPendencia(){} @PrePersist void pre(){if(dataInclusao==null)dataInclusao=java.time.OffsetDateTime.now();} public Long getId(){return id;} public void setId(Long v){this.id=v;} public Long getOrdemServicoId(){return ordemServicoId;} public void setOrdemServicoId(Long v){this.ordemServicoId=v;} public Short getTipoPendenciaId(){return tipoPendenciaId;} public void setTipoPendenciaId(Short v){this.tipoPendenciaId=v;} public String getDescricao(){return descricao;} public void setDescricao(String v){this.descricao=v;} public java.time.OffsetDateTime getDataInclusao(){return dataInclusao;} public java.time.OffsetDateTime getDataResolucao(){return dataResolucao;} public void setDataResolucao(java.time.OffsetDateTime v){this.dataResolucao=v;} public boolean getResolvida(){return resolvida;} public void setResolvida(boolean v){this.resolvida=v;} public Long getUsuarioCodigo(){return usuarioCodigo;} public void setUsuarioCodigo(Long v){this.usuarioCodigo=v;} public boolean isResolvida(){return resolvida;} }
